mapper.select:
select n.id as id, coalesce(split_part(n.img_uris, ',', 1), '') as cover, n.title as title, coalesce(n.topic_name, '') as topic, n.type as type, u.nickname as creator_nickname, u.avatar as creator_avatar, to_char(n.create_time, 'YYYY-MM-DD HH24:MI:SS') as create_time, to_char(n.update_time, 'YYYY-MM-DD HH24:MI:SS') as update_time, coalesce(nc.like_total, 0) as like_total, coalesce(nc.collect_total, 0) as collect_total, coalesce(nc.comment_total, 0) as comment_total from t_note n left join t_user u on n.creator_id = u.id left join t_note_count nc on n.id = nc.note_id where n.visible = 0 and n.status = 1
and n.id = #{noteId}
and u.id = #{userId}
order by n.id
